import os

from openai import OpenAI


def get_embeddings_client(config=None):
    config = config or {}
    api_key = config.get('api_key') or os.environ['OPENAI_API_KEY']
    return OpenAI(api_key=api_key)

from typing import List


class EmbeddingRequest:
    def __init__(self, texts: List[str]):
        self.texts = texts


class EmbeddingResponse:
    def __init__(self, embeddings: List[List[float]], query_embedding: List[float] = None, document_embeddings: List[List[float]] = None):
        self.embeddings = embeddings
        self.query_embedding = query_embedding
        self.document_embeddings = document_embeddings

import re


def corpus_safety(text):
    if re.search(r'[^a-zA-Z0-9\s]', text):
        return {'safe': False, 'reason': 'Contains non-alphanumeric characters'}
    return {'safe': True}
